            FROM "FA_TALI_DETAILES" "t"
            WHERE "t"."ID_HEADERS_TALI" = "v_tali_id"
              AND "t"."CODE_GROUPE_KALA" = "g_rows"(i)."CODE_KALA";

            IF "v_tali_number" = 0
            AND "v_tali_weight" = 0
